(() => {
  const g=window.drifter;
  const checks=[];
  const check=(condition, message)=>{if(!condition)throw new Error(message);checks.push(message);};
  const gp={index:0,connected:true,mapping:'standard',id:'Xbox Elite Wireless Controller Series 2',axes:[0,0,0,0],buttons:Array.from({length:17},()=>({pressed:false,value:0}))};
  Object.defineProperty(navigator,'getGamepads',{value:()=>[gp],configurable:true});
  const button=(i,on)=>gp.buttons[i]={pressed:on,value:on?1:0};
  const cell=()=>({group:{hm:'222',order:4},structure:4,freedom:3,variants:9,ability:'weave',blurb:'test cell'});
  g.begin();g.run.spawnIn=1e6;g.run.world.calm=1e6;
  let r=g.run;r.entities=[];r.cells=[cell(),cell(),cell(),cell()];
  button(2,true);g.update(1/60);
  check(r.structures.length===0,'X press does not place until released');
  button(2,false);g.update(1/60);
  check(r.structures.length===1,'X tap places exactly one structure');
  r.you.x=r.structures[0].x;r.you.y=r.structures[0].y;
  button(2,true);
  for(let i=0;i<56;i++)g.update(1/60);
  check(r.organelles.length===1,'X hold grows one mitochondrion');
  check(r.cells.length===1,'mitochondrion consumes exactly two cells');
  button(2,false);g.update(1/60);
  check(r.structures.length===1,'release after growing does not also place a cell');
  r.bond.companions=[{form:'strider',hm:'222',rank:1},{form:'warden',hm:'222',rank:1}];
  button(9,true);g.update(1/60);button(9,false);g.update(1/60);
  check(g.paused,'Start pauses');
  button(1,true);g.update(1/60);button(1,false);g.update(1/60);
  check(r.bond.active===1,'B switches companion while paused');
  button(9,true);g.update(1/60);button(9,false);g.update(1/60);
  check(!g.paused,'Start resumes');
  r.phase='reign';r.structures=[];r.bodies=[];r.organelles=[];r.bolts=[];r.you.iframe=100;
  r.throne={hm:'222',fed:['222'],mass:4,freedom:3,anchored:true,hp:14,maxHp:70,x:r.you.x+35e-6,y:r.you.y,awake:true,beat:100,spin:0};
  button(3,true);
  for(let i=0;i<185 && r.phase==='reign';i++)g.update(1/60);
  check(r.phase==='birth','Y hold tames a weakened boss in live simulation');
  check(r.throne.hp===14,'taming preserves the boss');
  check(r.bond.companions[0].rank===2,'repeated taming strengthens its companion');
  g.draw();
  button(3,false);g.update(1/60);button(9,true);g.update(1/60);button(9,false);g.update(1/60);
  check(r.phase==='settle' && r.world.aeon===2,'Start enters the next world after taming');
  check(r.bond.companions.length===2,'companions persist between worlds');
  g.draw();
  check(document.body.scrollHeight<=innerHeight+2,'game and controls fit the viewport');
  return checks;
})()
